def compute(vars):
    value = vars["v1"] + vars["v2"] + vars["v3"]
    return {
        "value": value,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "v3": vars["v3"],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "square feet"
            }
        }
    }
